-- CANONICAL SOURCE: shared/ui/Panel.lua. Staged copies under addons/*/*/Shared/UI/ are
-- generated by scripts/sync-shared.sh - never edit them; edit this file and re-sync.
--[[
    shared/ui/Panel.lua - Titled section panel, divider and label/value row.

    Generic building blocks for "card" style layouts. Everything is drawn from
    PHUI tokens (backdrops, colors, fonts, spacing); callers only choose content.
]]

local _, addon = ...

addon.UI = addon.UI or {}
addon.UI.Panel = addon.UI.Panel or {}
local Panel = addon.UI.Panel
local PHUI = addon.UI.PHUI

local TITLE_HEIGHT = 18

-- opts: width, height (optional; may be set later), title (optional text)
-- Returns the panel frame. `panel.body` is a child frame inset below the title
-- that callers parent their content to.
function Panel:Create(parent, opts)
    opts = opts or {}
    local pad = PHUI.Spacing.PANEL_PADDING
    local panel = CreateFrame("Frame", nil, parent, "BackdropTemplate")
    if opts.width and opts.height then
        panel:SetSize(opts.width, opts.height)
    end
    PHUI.ApplyBackdrop(panel, {
        backdrop = PHUI.Backdrops.ROUNDED_SMALL,
        bgColor = PHUI.Colors.BG_DARK,
        borderColor = PHUI.Colors.DIVIDER,
    })

    local top = pad
    if opts.title then
        panel.title = PHUI.CreateLabel(panel, "primary", opts.title, PHUI.Fonts.NORMAL)
        panel.title:SetPoint("TOPLEFT", panel, "TOPLEFT", pad, -pad + 2)
        top = pad + TITLE_HEIGHT
    end

    panel.body = CreateFrame("Frame", nil, panel)
    panel.body:SetPoint("TOPLEFT", panel, "TOPLEFT", pad, -top)
    panel.body:SetPoint("BOTTOMRIGHT", panel, "BOTTOMRIGHT", -pad, pad)
    return panel
end

-- Thin line in the shared divider color. orientation: "horizontal" (default)
-- or "vertical". Caller anchors it; thickness is 1px.
function Panel:CreateDivider(parent, orientation)
    local d = parent:CreateTexture(nil, "ARTWORK")
    local c = PHUI.Colors.DIVIDER
    d:SetColorTexture(c[1], c[2], c[3], c[4] or 1)
    if orientation == "vertical" then
        d:SetWidth(1)
    else
        d:SetHeight(1)
    end
    return d
end

-- "Label ........ value" row. opts: width, height (default 16),
-- valueStyle (PHUI text style, default "primary").
function Panel:CreateRow(parent, labelText, valueText, opts)
    opts = opts or {}
    local row = CreateFrame("Frame", nil, parent)
    row:SetSize(opts.width or 100, opts.height or 16)
    row.label = PHUI.CreateLabel(row, "muted", labelText, PHUI.Fonts.NORMAL)
    row.label:SetPoint("LEFT", row, "LEFT", 0, 0)
    row.value = PHUI.CreateLabel(row, opts.valueStyle or "primary", valueText, PHUI.Fonts.NORMAL)
    row.value:SetPoint("RIGHT", row, "RIGHT", 0, 0)
    row.value:SetJustifyH("RIGHT")
    function row:SetValue(text, style)
        self.value:SetText(text)
        if style then PHUI.ApplyTextStyle(self.value, style) end
    end
    return row
end

-- Bordered text button in PHUI styling (hover = gold border).
-- opts: width (80), height (22), textStyle (default "primary"), onClick.
function Panel:CreateButton(parent, text, opts)
    opts = opts or {}
    local button = CreateFrame("Button", nil, parent, "BackdropTemplate")
    button:SetSize(opts.width or 80, opts.height or 22)
    PHUI.ApplyBackdrop(button, { backdrop = PHUI.Backdrops.ICON_BUTTON, bgColor = PHUI.Colors.BG_DARK })
    button.label = PHUI.CreateLabel(button, opts.textStyle or "primary", text, PHUI.Fonts.NORMAL)
    button.label:SetPoint("CENTER", button, "CENTER", 0, 0)
    button:SetScript("OnEnter", function(self)
        local g = PHUI.Colors.ACCENT_GOLD
        self:SetBackdropBorderColor(g[1], g[2], g[3], 1)
    end)
    button:SetScript("OnLeave", function(self)
        local b = PHUI.Colors.BORDER_BRONZE
        self:SetBackdropBorderColor(b[1], b[2], b[3], 1)
    end)
    if opts.onClick then
        button:SetScript("OnClick", function(self)
            if not self.isActionDisabled then opts.onClick(self) end
        end)
    end
    function button:SetText(t)
        self.label:SetText(t)
    end
    return button
end
